// app/src/main/java/com/UIN/Tool/core/plugin/PluginWebInterface.kt
package com.UIN.Tool.core.plugin

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Vibrator
import android.os.Build
import android.webkit.JavascriptInterface
import android.widget.Toast
import com.UIN.Tool.log.Logger
import org.json.JSONObject

class PluginWebInterface(
    private val context: Context,
    private val pluginId: String,
    private val proxy: WebPluginProxy?
) {

    private val TAG = "PluginWebInterface"

    @JavascriptInterface
    fun callPlugin(method: String, params: String?) {
        Logger.i(TAG, "JS 调用插件: $method, 参数: $params")
        proxy?.onJsCall(method, params)
    }

    @JavascriptInterface
    fun callHost(action: String, data: String?) {
        Logger.i(TAG, "JS 调用宿主: $action, 数据: $data")
        val params = data ?: ""

        when (action) {
            "toast" -> showToast(params)
            "finish" -> (context as? Activity)?.finish()
            "log" -> Logger.i("WebPlugin", params)
            "alert" -> showAlert(params)
            "confirm" -> showConfirm(params)
            "vibrate" -> vibrate(params)
            "copy" -> copyToClipboard(params)
            "openUrl" -> openUrl(params)
            "share" -> share(params)
            else -> Logger.w(TAG, "未知的宿主调用: $action")
        }
    }

    @JavascriptInterface
    fun sendEvent(eventName: String, data: String?) {
        Logger.d(TAG, "发送事件: $eventName")
        proxy?.sendEvent(eventName, data)
    }

    // ==================== 新增/补全的方法 ====================

    private fun showToast(message: String) {
        (context as? Activity)?.runOnUiThread {
            Toast.makeText(context, message, Toast.LENGTH_SHORT).show()
        } ?: Toast.makeText(context, message, Toast.LENGTH_SHORT).show()
    }

    private fun showAlert(message: String) {
        (context as? Activity)?.runOnUiThread {
            android.app.AlertDialog.Builder(context)
                .setTitle("提示")
                .setMessage(message)
                .setPositiveButton("确定", null)
                .show()
        }
    }

    private fun showConfirm(message: String) {
        (context as? Activity)?.runOnUiThread {
            android.app.AlertDialog.Builder(context)
                .setTitle("确认")
                .setMessage(message)
                .setPositiveButton("确定") { _, _ -> }
                .setNegativeButton("取消") { _, _ -> }
                .show()
        }
    }

    private fun vibrate(durationMs: String) {
        try {
            val vibrator = context.getSystemService(Context.VIBRATOR_SERVICE) as Vibrator
            val duration = durationMs.toLongOrNull() ?: 200
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                vibrator.vibrate(
                    android.os.VibrationEffect.createOneShot(
                        duration,
                        android.os.VibrationEffect.DEFAULT_AMPLITUDE
                    )
                )
            } else {
                vibrator.vibrate(duration)
            }
            Logger.i(TAG, "震动: ${duration}ms")
        } catch (e: Exception) {
            Logger.e(TAG, "震动失败: ${e.message}")
        }
    }

    private fun copyToClipboard(text: String) {
        if (text.isEmpty()) {
            showToast("内容为空")
            return
        }
        try {
            val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
            val clip = android.content.ClipData.newPlainText("plugin_text", text)
            clipboard.setPrimaryClip(clip)
            showToast("已复制到剪贴板")
            Logger.i(TAG, "复制到剪贴板: ${text.take(50)}...")
        } catch (e: Exception) {
            Logger.e(TAG, "复制失败", e)
            showToast("复制失败: ${e.message}")
        }
    }

    private fun openUrl(url: String) {
        if (url.isEmpty()) {
            showToast("URL不能为空")
            return
        }
        try {
            val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url))
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            context.startActivity(intent)
            Logger.i(TAG, "打开链接: $url")
        } catch (e: Exception) {
            showToast("无法打开链接")
            Logger.e(TAG, "打开链接失败: ${e.message}")
        }
    }

    private fun share(text: String) {
        if (text.isEmpty()) {
            showToast("内容为空")
            return
        }
        try {
            val intent = Intent(Intent.ACTION_SEND).apply {
                type = "text/plain"
                putExtra(Intent.EXTRA_TEXT, text)
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            }
            context.startActivity(Intent.createChooser(intent, "分享"))
            Logger.i(TAG, "分享: ${text.take(50)}...")
        } catch (e: Exception) {
            Logger.e(TAG, "分享失败", e)
            showToast("分享失败: ${e.message}")
        }
    }
}

package com.UIN.Tool.core.plugin

import android.content.Context
import android.os.Bundle
import android.view.View
import android.view.ViewGroup
import android.webkit.WebView
import android.webkit.WebViewClient
import com.UIN.Tool.domain.model.PluginInfo
import com.UIN.Tool.log.Logger
import com.UIN.Tool.utils.Constants
import java.io.File

/**
 * Web 插件代理类 - 实现 PluginInterface 接口，内部使用 WebView 渲染
 */
class WebPluginProxy(
    private val pluginId: String,
    private val pluginDir: String,
    private val pluginInfo: PluginInfo
) : PluginInterface {

    private val TAG = "WebPluginProxy"
    private var context: Context? = null
    private var webView: WebView? = null
    private var isWebViewReady = false
    private val entryFile: String = pluginInfo.entry.ifEmpty { Constants.PLUGIN_WEB_INDEX }

    override fun onCreateView(
        context: Context,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View? {
        this.context = context

        webView = WebView(context).apply {
            settings.apply {
                javaScriptEnabled = true
                domStorageEnabled = true
                allowFileAccess = true
                allowFileAccessFromFileURLs = true
                allowUniversalAccessFromFileURLs = true
                setSupportZoom(true)
                builtInZoomControls = true
                displayZoomControls = false
                loadWithOverviewMode = true
                useWideViewPort = true
                defaultTextEncodingName = "UTF-8"
            }

            // 设置 WebViewClient
            webViewClient = object : WebViewClient() {
                override fun onPageFinished(view: WebView, url: String) {
                    super.onPageFinished(view, url)
                    isWebViewReady = true
                    Logger.success(TAG, "WebView 加载完成: ${pluginInfo.name}")
                }

                override fun onReceivedError(
                    view: WebView,
                    errorCode: Int,
                    description: String,
                    failingUrl: String
                ) {
                    Logger.e(TAG, "WebView 加载错误: $description")
                    val errorHtml = """
                        <html><body style='padding:20px;text-align:center;font-family:sans-serif'>
                        <h3>插件加载失败</h3>
                        <p>$description</p>
                        <p style='font-size:12px;color:#999'>$failingUrl</p>
                        </body></html>
                    """.trimIndent()
                    view.loadData(errorHtml, "text/html", "UTF-8")
                }
            }

            // 设置 JS 接口
            val proxy = this@WebPluginProxy
            val jsInterface = PluginWebInterface(context, pluginId, proxy)
            addJavascriptInterface(jsInterface, "UINPlugin")

            // 加载本地 HTML 文件
            val indexPath = "$pluginDir/$entryFile"
            val indexFile = File(indexPath)

            if (indexFile.exists()) {
                loadUrl("file://$indexPath")
                Logger.i(TAG, "加载 Web 插件: $indexPath")
            } else {
                val defaultHtml = getDefaultHtml()
                loadDataWithBaseURL("file://$pluginDir/web/", defaultHtml, "text/html", "UTF-8", null)
                Logger.w(TAG, "入口文件不存在，使用默认页面: $indexPath")
            }
        }

        return webView
    }

    /**
     * JS 调用插件方法
     */
    fun onJsCall(method: String, params: String?) {
        when (method) {
            "getPluginInfo" -> sendEvent("pluginInfo", pluginInfo.toJson())
            "getDeviceInfo" -> {
                val dm = context?.resources?.displayMetrics
                val info = org.json.JSONObject().apply {
                    put("model", android.os.Build.MODEL)
                    put("manufacturer", android.os.Build.MANUFACTURER)
                    put("android", android.os.Build.VERSION.RELEASE)
                    put("api", android.os.Build.VERSION.SDK_INT)
                    dm?.let {
                        put("screenWidth", it.widthPixels)
                        put("screenHeight", it.heightPixels)
                        put("density", it.density)
                    }
                }
                sendEvent("deviceInfo", info.toString())
            }
            else -> Logger.d(TAG, "未处理的方法: $method")
        }
    }

    /**
     * 向 Web 端发送事件
     */
    fun sendEvent(eventName: String, data: String?) {
        if (webView != null && isWebViewReady) {
            val js = """
                if (window.dispatchEvent && window.dispatchEvent instanceof Function) {
                    window.dispatchEvent(new CustomEvent('$eventName', { detail: ${data ?: "null"} }));
                } else if (window.on$eventName) {
                    window.on$eventName(${data ?: "null"});
                }
            """.trimIndent()
            webView?.evaluateJavascript(js, null)
        }
    }

    override fun onResume() {
        webView?.let {
            it.onResume()
            it.resumeTimers()
        }
        sendEvent("resume", "{}")
    }

    override fun onPause() {
        webView?.let {
            it.onPause()
            it.pauseTimers()
        }
        sendEvent("pause", "{}")
    }

    override fun onDestroy() {
        sendEvent("destroy", "{}")
        webView?.let {
            it.loadUrl("about:blank")
            it.clearHistory()
            it.clearCache(true)
            it.clearFormData()
            it.destroy()
        }
        webView = null
    }

    override fun onBackPressed(): Boolean {
        webView?.let {
            if (it.canGoBack()) {
                it.goBack()
                return true
            }
        }
        return false
    }

    override fun onSaveInstanceState(): Bundle? {
        return Bundle().apply {
            webView?.saveState(this)
        }
    }

    private fun getDefaultHtml(): String {
        return """
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="UTF-8">
                <meta name="viewport" content="width=device-width, initial-scale=1.0">
                <title>${pluginInfo.name}</title>
                <style>
                    body { font-family: sans-serif; padding: 20px; text-align: center; }
                    button { background: #37474F; color: white; border: none; padding: 12px 24px; border-radius: 8px; margin: 10px; }
                    .info { background: #f0f0f0; padding: 16px; border-radius: 12px; margin-top: 20px; text-align: left; }
                </style>
            </head>
            <body>
                <h1>${pluginInfo.name}</h1>
                <p>${pluginInfo.description ?: ""}</p>
                <button onclick="UINPlugin.callHost('toast', 'Hello from Web Plugin!')">点我</button>
                <button onclick="UINPlugin.callHost('finish', '')">关闭</button>
                <div class="info">
                    <strong>插件信息</strong><br>
                    版本: ${pluginInfo.versionName}<br>
                    作者: ${pluginInfo.author ?: "未知"}<br>
                    ID: $pluginId
                </div>
                <script>
                    window.addEventListener('resume', function(e) { console.log('插件恢复', e.detail); });
                    window.addEventListener('pause', function(e) { console.log('插件暂停', e.detail); });
                </script>
            </body>
            </html>
        """.trimIndent()
    }
}

package com.UIN.Tool.core.update

import android.content.Context
import com.UIN.Tool.data.local.PreferenceManager
import com.UIN.Tool.log.Logger
import com.UIN.Tool.utils.Constants
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONArray
import java.io.IOException
import java.util.concurrent.TimeUnit

class ForceUpdateChecker(
    private val context: Context,
    private val preferenceManager: PreferenceManager
) {

    companion object {
        private const val TAG = "ForceUpdateChecker"
        private const val GITHUB_API = "https://api.github.com/repos/Undefined-Invalid-Null/UIN-Tool/releases"
    }

    private val client = OkHttpClient.Builder()
        .connectTimeout(10, TimeUnit.SECONDS)
        .readTimeout(10, TimeUnit.SECONDS)
        .writeTimeout(10, TimeUnit.SECONDS)
        .build()

    interface ForceUpdateCallback {
        fun onResult(forceUpdate: Boolean)
        fun onError(error: String)
    }

    fun checkForceUpdate(callback: ForceUpdateCallback) {
        android.os.Handler(android.os.Looper.getMainLooper()).post {
            try {
                Logger.enter(TAG, "checkForceUpdate")

                val currentVersionCode = getCurrentVersionCode()
                Logger.param(TAG, "当前版本代码", currentVersionCode)

                // 在后台线程执行网络请求
                Thread {
                    try {
                        val request = Request.Builder()
                            .url("$GITHUB_API?per_page=1")
                            .header("Accept", "application/vnd.github.v3+json")
                            .header("User-Agent", "UIN-Tool-Android")
                            .build()

                        val response = client.newCall(request).execute()
                        if (!response.isSuccessful) {
                            Logger.e(TAG, "API请求失败: ${response.code}")
                            android.os.Handler(android.os.Looper.getMainLooper()).post {
                                callback.onResult(false)
                            }
                            return@Thread
                        }

                        val body = response.body?.string()
                        if (body.isNullOrEmpty()) {
                            android.os.Handler(android.os.Looper.getMainLooper()).post {
                                callback.onResult(false)
                            }
                            return@Thread
                        }

                        val releases = JSONArray(body)
                        if (releases.length() == 0) {
                            android.os.Handler(android.os.Looper.getMainLooper()).post {
                                callback.onResult(false)
                            }
                            return@Thread
                        }

                        val latest = releases.getJSONObject(0)
                        val tagName = latest.optString("tag_name", "")
                        val parts = tagName.split("-", limit = 3)

                        val newVersionCode = parts.getOrNull(0)?.toIntOrNull() ?: 0
                        val forceFlag = parts.getOrNull(2) ?: "0"

                        val hasNewer = newVersionCode > currentVersionCode
                        val isForceUpdate = forceFlag == "1"

                        Logger.param(TAG, "最新版本代码", newVersionCode)
                        Logger.param(TAG, "强制更新标志", forceFlag)
                        Logger.param(TAG, "需要强制更新", isForceUpdate)

                        if (hasNewer && isForceUpdate) {
                            val ignoredTag = preferenceManager.getForceUpdateIgnored()
                            if (tagName == ignoredTag) {
                                Logger.i(TAG, "强制更新已被忽略: $tagName")
                                android.os.Handler(android.os.Looper.getMainLooper()).post {
                                    callback.onResult(false)
                                }
                                return@Thread
                            }
                            android.os.Handler(android.os.Looper.getMainLooper()).post {
                                callback.onResult(true)
                            }
                        } else {
                            android.os.Handler(android.os.Looper.getMainLooper()).post {
                                callback.onResult(false)
                            }
                        }

                    } catch (e: IOException) {
                        Logger.e(TAG, "网络请求失败", e)
                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                            callback.onError("网络请求失败: ${e.message}")
                        }
                    } catch (e: Exception) {
                        Logger.e(TAG, "检查强制更新失败", e)
                        android.os.Handler(android.os.Looper.getMainLooper()).post {
                            callback.onError(e.message ?: "检查失败")
                        }
                    }
                }.start()

            } catch (e: Exception) {
                Logger.e(TAG, "检查强制更新失败", e)
                callback.onError(e.message ?: "检查失败")
            } finally {
                Logger.exit(TAG, "checkForceUpdate", System.currentTimeMillis())
            }
        }
    }

    suspend fun checkForceUpdate(): Boolean {
        return withContext(Dispatchers.IO) {
            try {
                Logger.enter(TAG, "checkForceUpdate")

                val currentVersionCode = getCurrentVersionCode()

                val request = Request.Builder()
                    .url("$GITHUB_API?per_page=1")
                    .header("Accept", "application/vnd.github.v3+json")
                    .header("User-Agent", "UIN-Tool-Android")
                    .build()

                client.newCall(request).execute().use { response ->
                    if (!response.isSuccessful) {
                        Logger.e(TAG, "API请求失败: ${response.code}")
                        return@withContext false
                    }

                    val body = response.body?.string() ?: return@withContext false
                    val releases = JSONArray(body)

                    if (releases.length() == 0) {
                        return@withContext false
                    }

                    val latest = releases.getJSONObject(0)
                    val tagName = latest.optString("tag_name", "")
                    val parts = tagName.split("-", limit = 3)

                    val newVersionCode = parts.getOrNull(0)?.toIntOrNull() ?: 0
                    val forceFlag = parts.getOrNull(2) ?: "0"

                    val hasNewer = newVersionCode > currentVersionCode
                    val isForceUpdate = forceFlag == "1"

                    Logger.param(TAG, "当前版本", currentVersionCode)
                    Logger.param(TAG, "最新版本", newVersionCode)
                    Logger.param(TAG, "强制更新", isForceUpdate)

                    if (hasNewer && isForceUpdate) {
                        val ignoredTag = preferenceManager.getForceUpdateIgnored()
                        if (tagName == ignoredTag) {
                            Logger.i(TAG, "强制更新已被忽略: $tagName")
                            return@withContext false
                        }
                        return@withContext true
                    }
                }

                false

            } catch (e: Exception) {
                Logger.e(TAG, "检查强制更新失败", e)
                false
            } finally {
                Logger.exit(TAG, "checkForceUpdate", System.currentTimeMillis())
            }
        }
    }

    private fun getCurrentVersionCode(): Int {
        return try {
            val packageInfo = context.packageManager.getPackageInfo(context.packageName, 0)
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.P) {
                packageInfo.longVersionCode.toInt()
            } else {
                packageInfo.versionCode
            }
        } catch (e: Exception) {
            1
        }
    }
}

package com.UIN.Tool.core.update

import android.content.Context
import android.content.pm.PackageManager
import android.os.Build
import com.UIN.Tool.data.local.PreferenceManager
import com.UIN.Tool.domain.model.ReleaseInfo
import com.UIN.Tool.log.Logger
import com.UIN.Tool.utils.Constants
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.net.HttpURLConnection
import java.net.URL
import java.util.concurrent.TimeUnit

class UpdateChecker(
    private val context: Context,
    private val preferenceManager: PreferenceManager
) {

    companion object {
        private const val TAG = "UpdateChecker"
        private const val GITHUB_API = "https://api.github.com/repos/Undefined-Invalid-Null/UIN-Tool/releases"
        private val DEFAULT_MIRRORS = listOf(
            "https://hub.fastgit.xyz",
            "https://github.moeyy.xyz",
            "https://ghproxy.net",
            "https://mirror.ghproxy.com",
            "https://gh.api.99988866.xyz",
            "https://gitclone.com"
        )
    }

    private val client = OkHttpClient.Builder()
        .connectTimeout(Constants.NETWORK_TIMEOUT, TimeUnit.SECONDS)
        .readTimeout(Constants.NETWORK_READ_TIMEOUT, TimeUnit.SECONDS)
        .writeTimeout(Constants.NETWORK_WRITE_TIMEOUT, TimeUnit.SECONDS)
        .cache(okhttp3.Cache(File(context.cacheDir, "okhttp_cache"), Constants.CACHE_SIZE))
        .build()

    private var currentMirror: String? = null
    private var onUpdateListener: OnUpdateListener? = null

    interface OnUpdateListener {
        fun onCheckStart()
        fun onCheckSuccess(releases: List<ReleaseInfo>, hasNewer: Boolean, forceUpdate: Boolean)
        fun onCheckFailed(error: String)
        fun onNoUpdate(currentVersion: String)
    }

    fun setOnUpdateListener(listener: OnUpdateListener) {
        this.onUpdateListener = listener
    }

    fun checkUpdate() {
        onUpdateListener?.onCheckStart()
        Logger.enter(TAG, "checkUpdate")

        Thread {
            try {
                val currentVersionCode = getCurrentVersionCode()
                val currentVersionName = getCurrentVersionName()

                Logger.param(TAG, "当前版本", "$currentVersionName (代码: $currentVersionCode)")

                // 测试镜像站
                val workingUrl = testMirrors()
                if (workingUrl == null) {
                    Logger.e(TAG, "所有镜像均不可用")
                    android.os.Handler(android.os.Looper.getMainLooper()).post {
                        onUpdateListener?.onCheckFailed("网络连接失败，请检查网络后重试")
                    }
                    return@Thread
                }

                // 获取Releases
                val releases = fetchReleases(workingUrl)
                if (releases.isEmpty()) {
                    android.os.Handler(android.os.Looper.getMainLooper()).post {
                        onUpdateListener?.onNoUpdate(currentVersionName)
                    }
                    return@Thread
                }

                // 检查是否有新版本
                var hasNewer = false
                var forceUpdate = false

                for (release in releases) {
                    val versionCode = release.versionCode.toIntOrNull() ?: 0
                    if (versionCode > currentVersionCode) {
                        hasNewer = true
                        forceUpdate = release.forceUpdate

                        // 应用镜像到下载链接
                        currentMirror?.let { mirror ->
                            if (release.downloadUrl.startsWith("https://github.com")) {
                                release.downloadUrl = getMirrorDownloadUrl(mirror, release.downloadUrl)
                            }
                        }
                        break
                    }
                }

                Logger.param(TAG, "有新版本", hasNewer)
                Logger.param(TAG, "强制更新", forceUpdate)

                val finalReleases = releases
                val finalHasNewer = hasNewer
                val finalForceUpdate = forceUpdate

                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    onUpdateListener?.onCheckSuccess(finalReleases, finalHasNewer, finalForceUpdate)
                }

            } catch (e: Exception) {
                Logger.e(TAG, "检查更新失败", e)
                android.os.Handler(android.os.Looper.getMainLooper()).post {
                    onUpdateListener?.onCheckFailed(e.message ?: "检查更新失败")
                }
            } finally {
                Logger.exit(TAG, "checkUpdate", System.currentTimeMillis())
            }
        }.start()
    }

    private fun testMirrors(): String? {
        // 先尝试直连
        Logger.d(TAG, "测试直连: $GITHUB_API")
        if (testUrl(GITHUB_API)) {
            Logger.success(TAG, "直连可用")
            return GITHUB_API
        }

        // 获取启用的镜像
        val enabledMirrors = preferenceManager.getEnabledMirrors()
        val useCdn = preferenceManager.isUseCdn()

        val mirrorsToTest = if (enabledMirrors.isNotEmpty() && useCdn) {
            enabledMirrors
        } else {
            DEFAULT_MIRRORS
        }

        for (mirror in mirrorsToTest) {
            val testUrl = getMirrorUrl(mirror, GITHUB_API)
            Logger.d(TAG, "测试镜像: $testUrl")
            if (testUrl(testUrl)) {
                currentMirror = mirror
                Logger.success(TAG, "找到可用镜像: $mirror")
                return testUrl
            }
        }

        // 如果配置的镜像都不可用，尝试默认镜像
        if (enabledMirrors.isNotEmpty() && useCdn) {
            Logger.d(TAG, "配置镜像不可用，尝试默认镜像")
            for (mirror in DEFAULT_MIRRORS) {
                val testUrl = getMirrorUrl(mirror, GITHUB_API)
                if (testUrl(testUrl)) {
                    currentMirror = mirror
                    Logger.success(TAG, "找到可用默认镜像: $mirror")
                    return testUrl
                }
            }
        }

        return null
    }

    private fun testUrl(urlString: String): Boolean {
        return try {
            val url = URL(urlString)
            val connection = url.openConnection() as HttpURLConnection
            connection.connectTimeout = 8000
            connection.readTimeout = 8000
            connection.requestMethod = "HEAD"
            connection.setRequestProperty("Accept", "application/vnd.github.v3+json")
            connection.setRequestProperty("User-Agent", "UIN-Tool-Android")
            val responseCode = connection.responseCode
            connection.disconnect()
            responseCode == 200 || responseCode == 302 || responseCode == 301
        } catch (e: Exception) {
            false
        }
    }

    private fun fetchReleases(apiUrl: String): List<ReleaseInfo> {
        try {
            val url = "$apiUrl?per_page=30"
            val request = Request.Builder()
                .url(url)
                .header("Accept", "application/vnd.github.v3+json")
                .header("User-Agent", "UIN-Tool-Android")
                .build()

            val response = client.newCall(request).execute()
            if (!response.isSuccessful) {
                throw Exception("GitHub API错误: ${response.code}")
            }

            val body = response.body?.string() ?: return emptyList()
            return parseReleases(body)

        } catch (e: Exception) {
            Logger.e(TAG, "获取Releases失败", e)
            throw e
        }
    }

    private fun parseReleases(json: String): List<ReleaseInfo> {
        val releases = mutableListOf<ReleaseInfo>()
        val jsonArray = JSONArray(json)

        for (i in 0 until jsonArray.length()) {
            val release = jsonArray.getJSONObject(i)

            if (release.optBoolean("draft", false)) {
                continue
            }

            val tagName = release.optString("tag_name", "")
            val parts = tagName.split("-", limit = 3)

            val info = ReleaseInfo().apply {
                this.tagName = tagName
                releaseDate = release.optString("published_at", "")
                releaseNotes = release.optString("body", "")
                isPreRelease = release.optBoolean("prerelease", false)

                versionCode = parts.getOrNull(0) ?: "1"
                versionName = parts.getOrNull(1) ?: versionCode
                forceFlag = parts.getOrNull(2) ?: "0"
                forceUpdate = forceFlag == "1"

                val assets = release.optJSONArray("assets")
                if (assets != null) {
                    for (j in 0 until assets.length()) {
                        val asset = assets.getJSONObject(j)
                        if (asset.getString("name").endsWith(".apk")) {
                            downloadUrl = asset.getString("browser_download_url")
                            apkSize = asset.getLong("size")
                            break
                        }
                    }
                }

                if (downloadUrl.isEmpty()) {
                    downloadUrl = "https://github.com/Undefined-Invalid-Null/UIN-Tool/releases/tag/$tagName"
                }
            }

            releases.add(info)
        }

        releases.sortByDescending { it.versionCode.toIntOrNull() ?: 0 }

        return releases
    }

    private fun getMirrorUrl(mirror: String, originalUrl: String): String {
        return when {
            mirror.contains("ghproxy") -> "$mirror/$originalUrl"
            mirror.contains("fastgit") -> originalUrl.replace("https://api.github.com", "$mirror/api.github.com")
            mirror.contains("moeyy") -> "$mirror/$originalUrl"
            else -> "$mirror/$originalUrl"
        }
    }

    private fun getMirrorDownloadUrl(mirror: String, originalUrl: String): String {
        return when {
            mirror.contains("ghproxy") -> "$mirror/$originalUrl"
            mirror.contains("fastgit") -> originalUrl.replace("https://github.com", "$mirror/github.com")
            else -> originalUrl
        }
    }

    private fun getCurrentVersionCode(): Int {
        return try {
            val packageInfo = context.packageManager.getPackageInfo(context.packageName, 0)
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                packageInfo.longVersionCode.toInt()
            } else {
                packageInfo.versionCode
            }
        } catch (e: Exception) {
            1
        }
    }

    private fun getCurrentVersionName(): String {
        return try {
            context.packageManager.getPackageInfo(context.packageName, 0).versionName ?: "1.0.0"
        } catch (e: Exception) {
            "1.0.0"
        }
    }

    fun ignoreVersion(versionName: String) {
        preferenceManager.setIgnoredVersion(versionName)
        Logger.i(TAG, "忽略版本: $versionName")
    }

    fun ignoreForceUpdate(tagName: String) {
        preferenceManager.setForceUpdateIgnored(tagName)
        Logger.i(TAG, "忽略强制更新: $tagName")
    }
}

package com.UIN.Tool.core.update

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.os.Environment
import androidx.core.app.NotificationCompat
import androidx.core.content.FileProvider
import com.UIN.Tool.MainActivity
import com.UIN.Tool.log.Logger
import com.UIN.Tool.utils.Constants
import okhttp3.OkHttpClient
import okhttp3.Request
import java.io.File
import java.io.FileOutputStream
import java.util.concurrent.TimeUnit

class UpdateDownloader(
    private val context: Context
) {

    companion object {
        private const val TAG = "UpdateDownloader"
        private const val CHANNEL_ID = "update_download_channel"
        private const val NOTIFICATION_ID = 1001
    }

    private var onDownloadListener: OnDownloadListener? = null
    private var isDownloading = false
    private var downloadThread: Thread? = null

    private val client = OkHttpClient.Builder()
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(60, TimeUnit.SECONDS)
        .writeTimeout(60, TimeUnit.SECONDS)
        .build()

    private val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

    interface OnDownloadListener {
        fun onStart()
        fun onProgress(progress: Int, downloaded: Long, total: Long)
        fun onSuccess(file: File)
        fun onFailed(error: String)
    }

    init {
        createNotificationChannel()
    }

    fun setOnDownloadListener(listener: OnDownloadListener) {
        this.onDownloadListener = listener
    }

    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                "更新下载",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "应用更新下载进度"
                setShowBadge(false)
            }
            notificationManager.createNotificationChannel(channel)
        }
    }

    fun startDownload(downloadUrl: String, versionName: String) {
        if (isDownloading) {
            Logger.w(TAG, "下载正在进行中")
            return
        }

        isDownloading = true
        onDownloadListener?.onStart()

        // 创建下载目录
        val downloadDir = File(Constants.DOWNLOAD_DIR)
        if (!downloadDir.exists()) {
            downloadDir.mkdirs()
        }

        // 清理版本号前缀
        val cleanVersion = versionName.replace(Regex("^[vV]"), "")
        val fileName = "UIN_Tool_v${cleanVersion}.apk"
        val file = File(downloadDir, fileName)

        if (file.exists()) {
            file.delete()
        }

        Logger.i(TAG, "开始下载: $downloadUrl")
        Logger.param(TAG, "保存路径", file.absolutePath)

        // 显示通知
        showNotification(versionName)

        downloadThread = Thread {
            try {
                val request = Request.Builder()
                    .url(downloadUrl)
                    .header("User-Agent", "UIN-Tool-Android")
                    .build()

                val response = client.newCall(request).execute()
                if (!response.isSuccessful) {
                    throw Exception("下载失败: ${response.code}")
                }

                val body = response.body ?: throw Exception("响应体为空")
                val contentLength = body.contentLength()

                FileOutputStream(file).use { fos ->
                    body.byteStream().use { inputStream ->
                        val buffer = ByteArray(8192)
                        var bytesRead: Int
                        var downloaded = 0L
                        var lastProgress = -1

                        while (inputStream.read(buffer).also { bytesRead = it } != -1) {
                            // 检查是否被取消
                            if (!isDownloading) {
                                fos.close()
                                file.delete()
                                throw Exception("下载已取消")
                            }

                            fos.write(buffer, 0, bytesRead)
                            downloaded += bytesRead

                            val progress = if (contentLength > 0) {
                                (downloaded * 100 / contentLength).toInt()
                            } else 0

                            if (progress != lastProgress) {
                                lastProgress = progress
                                updateNotification(progress, downloaded, contentLength)
                                onDownloadListener?.onProgress(progress, downloaded, contentLength)
                                Logger.d(TAG, "下载进度: $progress%")
                            }
                        }
                    }
                }

                Logger.success(TAG, "下载完成: ${file.absolutePath}")

                notificationManager.cancel(NOTIFICATION_ID)
                isDownloading = false
                onDownloadListener?.onSuccess(file)

            } catch (e: Exception) {
                Logger.e(TAG, "下载失败", e)
                notificationManager.cancel(NOTIFICATION_ID)
                isDownloading = false
                onDownloadListener?.onFailed(e.message ?: "下载失败")
            }
        }

        downloadThread?.start()
    }

    fun cancelDownload() {
        isDownloading = false
        downloadThread?.interrupt()
        notificationManager.cancel(NOTIFICATION_ID)
        Logger.i(TAG, "下载已取消")
    }

    fun installApk(file: File) {
        if (!file.exists()) {
            Logger.e(TAG, "APK文件不存在: ${file.absolutePath}")
            return
        }

        try {
            val uri = FileProvider.getUriForFile(
                context,
                "${context.packageName}.fileprovider",
                file
            )

            val intent = Intent(Intent.ACTION_VIEW).apply {
                setDataAndType(uri, "application/vnd.android.package-archive")
                addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            }

            context.startActivity(intent)
            Logger.success(TAG, "启动安装: ${file.name}")
        } catch (e: Exception) {
            Logger.e(TAG, "启动安装失败", e)
        }
    }

    private fun showNotification(versionName: String) {
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val pendingIntent = PendingIntent.getActivity(
            context,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setContentTitle("正在下载 UIN Tool $versionName")
            .setContentText("下载中... 0%")
            .setSmallIcon(android.R.drawable.stat_sys_download)
            .setContentIntent(pendingIntent)
            .setOngoing(true)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setProgress(100, 0, false)
            .build()

        notificationManager.notify(NOTIFICATION_ID, notification)
    }

    private fun updateNotification(progress: Int, downloaded: Long, total: Long) {
        val downloadedStr = formatSize(downloaded)
        val totalStr = formatSize(total)

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setContentTitle("正在下载更新")
            .setContentText("下载中... $progress% ($downloadedStr/$totalStr)")
            .setProgress(100, progress, false)
            .setSmallIcon(android.R.drawable.stat_sys_download)
            .setOngoing(true)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .build()

        notificationManager.notify(NOTIFICATION_ID, notification)
    }

    private fun formatSize(size: Long): String {
        return when {
            size <= 0 -> "0 B"
            size < 1024 -> "$size B"
            size < 1024 * 1024 -> String.format("%.2f KB", size / 1024.0)
            else -> String.format("%.2f MB", size / (1024.0 * 1024.0))
        }
    }
}

package com.UIN.Tool.data.local

import android.content.ContentResolver
import android.content.Context
import android.net.Uri
import com.UIN.Tool.log.Logger
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipInputStream
import java.util.zip.ZipOutputStream

class FileManager(private val context: Context) {

    private val TAG = "FileManager"

    fun copyUriToFile(uri: Uri, destFile: File): Boolean {
        return try {
            val resolver: ContentResolver = context.contentResolver
            resolver.openInputStream(uri)?.use { inputStream ->
                FileOutputStream(destFile).use { outputStream ->
                    inputStream.copyTo(outputStream)
                }
            }
            true
        } catch (e: Exception) {
            Logger.e(TAG, "复制Uri到文件失败", e)
            false
        }
    }

    fun readFileToString(file: File): String? {
        return try {
            if (!file.exists()) return null
            file.readText()
        } catch (e: Exception) {
            Logger.e(TAG, "读取文件失败: ${file.absolutePath}", e)
            null
        }
    }

    fun writeStringToFile(file: File, content: String): Boolean {
        return try {
            file.parentFile?.mkdirs()
            file.writeText(content)
            true
        } catch (e: Exception) {
            Logger.e(TAG, "写入文件失败: ${file.absolutePath}", e)
            false
        }
    }

    fun deleteRecursively(file: File): Boolean {
        return try {
            when {
                !file.exists() -> true
                file.isDirectory -> {
                    file.listFiles()?.forEach { deleteRecursively(it) }
                    file.delete()
                }
                else -> file.delete()
            }
        } catch (e: Exception) {
            Logger.e(TAG, "删除失败: ${file.absolutePath}", e)
            false
        }
    }

    fun copyDirectory(src: File, dst: File): Boolean {
        return try {
            if (!src.exists()) return false
            if (!dst.exists()) dst.mkdirs()

            src.listFiles()?.forEach { file ->
                val destFile = File(dst, file.name)
                if (file.isDirectory) {
                    copyDirectory(file, destFile)
                } else {
                    file.copyTo(destFile, overwrite = true)
                }
            }
            true
        } catch (e: Exception) {
            Logger.e(TAG, "复制目录失败", e)
            false
        }
    }

    fun zipDirectory(srcDir: File, destZip: File): Boolean {
        return try {
            destZip.parentFile?.mkdirs()
            if (destZip.exists()) destZip.delete()

            ZipOutputStream(FileOutputStream(destZip)).use { zos ->
                zipFileRecursive(srcDir, srcDir, zos)
            }
            true
        } catch (e: Exception) {
            Logger.e(TAG, "压缩目录失败", e)
            false
        }
    }

    private fun zipFileRecursive(rootDir: File, file: File, zos: ZipOutputStream) {
        if (file.isDirectory) {
            file.listFiles()?.forEach { child ->
                zipFileRecursive(rootDir, child, zos)
            }
        } else {
            try {
                val entryName = file.absolutePath
                    .removePrefix(rootDir.absolutePath)
                    .removePrefix("/")
                zos.putNextEntry(ZipEntry(entryName))
                FileInputStream(file).use { fis ->
                    fis.copyTo(zos)
                }
                zos.closeEntry()
            } catch (e: Exception) {
                Logger.e(TAG, "添加文件到ZIP失败: ${file.absolutePath}", e)
            }
        }
    }

    fun unzipFile(zipFile: File, destDir: File): Boolean {
        return try {
            destDir.mkdirs()
            ZipInputStream(FileInputStream(zipFile)).use { zis ->
                var entry: ZipEntry? = zis.nextEntry
                while (entry != null) {
                    val targetFile = File(destDir, entry.name)
                    if (entry.isDirectory) {
                        targetFile.mkdirs()
                    } else {
                        targetFile.parentFile?.mkdirs()
                        FileOutputStream(targetFile).use { fos ->
                            zis.copyTo(fos)
                        }
                    }
                    entry = zis.nextEntry
                }
            }
            true
        } catch (e: Exception) {
            Logger.e(TAG, "解压失败: ${zipFile.absolutePath}", e)
            false
        }
    }

    fun getFileSize(file: File): Long {
        return if (file.exists() && file.isFile) {
            file.length()
        } else if (file.exists() && file.isDirectory) {
            file.listFiles()?.sumOf { getFileSize(it) } ?: 0
        } else {
            0
        }
    }

    fun createDirectory(path: String): Boolean {
        return try {
            val dir = File(path)
            if (!dir.exists()) {
                dir.mkdirs()
            }
            true
        } catch (e: Exception) {
            Logger.e(TAG, "创建目录失败: $path", e)
            false
        }
    }
}

package com.UIN.Tool.data.local

import android.content.Context
import android.content.SharedPreferences
import com.UIN.Tool.utils.Constants

class PreferenceManager(private val context: Context) {

    private val prefs: SharedPreferences = context.getSharedPreferences(Constants.PREF_NAME, Context.MODE_PRIVATE)
    private val signaturePrefs: SharedPreferences = context.getSharedPreferences(Constants.PREF_PLUGIN_SIGNATURES, Context.MODE_PRIVATE)
    private val crashPrefs: SharedPreferences = context.getSharedPreferences(Constants.PREF_CRASH, Context.MODE_PRIVATE)
    private val mirrorPrefs: SharedPreferences = context.getSharedPreferences(Constants.PREF_GITHUB_MIRROR, Context.MODE_PRIVATE)

    // ==================== 工作目录 ====================

    fun getWorkFolder(): String {
        return prefs.getString(Constants.KEY_WORK_FOLDER, Constants.WORK_DIR) ?: Constants.WORK_DIR
    }

    fun setWorkFolder(path: String) {
        prefs.edit().putString(Constants.KEY_WORK_FOLDER, path).apply()
    }

    // ==================== 视图模式 ====================

    fun getViewMode(): String {
        return prefs.getString(Constants.KEY_VIEW_MODE, "list") ?: "list"
    }

    fun setViewMode(mode: String) {
        prefs.edit().putString(Constants.KEY_VIEW_MODE, mode).apply()
    }

    // ==================== 图标着色 ====================

    fun isUseCustomIconTint(): Boolean {
