package com.UIN.Tool.data.remote

import com.UIN.Tool.domain.model.RepoPluginInfo
import com.UIN.Tool.log.Logger
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONArray
import org.json.JSONObject
import java.util.concurrent.TimeUnit

class GitHubApiService(
    private val client: OkHttpClient
) {

    companion object {
        private const val TAG = "GitHubApiService"
        private const val GITHUB_API_BASE = "https://api.github.com"
        private const val GITHUB_ORG = "UIN-Tool-Plugins"
    }

    suspend fun fetchOrgRepos(): List<RepoPluginInfo> {
        val result = mutableListOf<RepoPluginInfo>()
        val url = "$GITHUB_API_BASE/orgs/$GITHUB_ORG/repos?per_page=100"

        try {
            val request = Request.Builder()
                .url(url)
                .header("Accept", "application/vnd.github.v3+json")
                .header("User-Agent", "UIN-Tool-Android")
                .build()

            client.newCall(request).execute().use { response ->
                if (response.isSuccessful) {
                    val json = response.body?.string() ?: return emptyList()
                    val repos = JSONArray(json)

                    for (i in 0 until repos.length()) {
                        val repo = repos.getJSONObject(i)
                        val repoName = repo.getString("name")

                        if (repoName == ".github" || repoName == "Docs" || repoName == "docs") {
                            continue
                        }

                        val description = repo.optString("description", "")
                        val plugin = fetchLatestRelease(repoName)
                        plugin?.let {
                            it.name = if (description.isNotEmpty()) description else repoName
                            result.add(it)
                        }
                    }
                }
            }
        } catch (e: Exception) {
            Logger.e(TAG, "获取仓库列表失败", e)
        }

        return result
    }

    suspend fun fetchLatestRelease(repoName: String): RepoPluginInfo? {
        val url = "$GITHUB_API_BASE/repos/$GITHUB_ORG/$repoName/releases/latest"

        return try {
            val request = Request.Builder()
                .url(url)
                .header("Accept", "application/vnd.github.v3+json")
                .header("User-Agent", "UIN-Tool-Android")
                .build()

            client.newCall(request).execute().use { response ->
                if (response.isSuccessful) {
                    val json = response.body?.string() ?: return null
                    parseRelease(repoName, json)
                } else {
                    null
                }
            }
        } catch (e: Exception) {
            Logger.e(TAG, "获取Release失败: $repoName", e)
            null
        }
    }

    private fun parseRelease(repoName: String, json: String): RepoPluginInfo? {
        return try {
            val release = JSONObject(json)
            val plugin = RepoPluginInfo()
            plugin.pluginId = repoName

            val tagName = release.optString("tag_name", "")
            if (tagName.contains("-")) {
                val parts = tagName.split("-", limit = 2)
                plugin.version = parts[0]
                plugin.versionName = if (parts.size > 1) parts[1] else parts[0]
            } else {
                plugin.version = "1"
                plugin.versionName = if (tagName.isNotEmpty()) tagName else "1.0.0"
            }

            plugin.updateLog = release.optString("body", "")
            plugin.lastUpdate = release.optString("published_at", "")
            plugin.repositoryUrl = release.optString("html_url", "")

            val assets = release.getJSONArray("assets")
            for (i in 0 until assets.length()) {
                val asset = assets.getJSONObject(i)
                if (asset.getString("name").endsWith(".tpk")) {
                    plugin.downloadUrl = asset.getString("browser_download_url")
                    plugin.size = asset.getLong("size")
                    break
                }
            }

            if (plugin.downloadUrl.isEmpty()) {
                return null
            }

            plugin.author = "UIN 社区"
            plugin.description = "UIN Tool 插件"
            plugin
        } catch (e: Exception) {
            Logger.e(TAG, "解析Release失败", e)
            null
        }
    }
}

package com.UIN.Tool.data.remote

import com.UIN.Tool.domain.model.MirrorItem
import com.UIN.Tool.log.Logger
import com.UIN.Tool.utils.Constants
import okhttp3.OkHttpClient
import okhttp3.Request
import java.util.concurrent.TimeUnit

class MirrorManager(
    private val client: OkHttpClient
) {

    companion object {
        private const val TAG = "MirrorManager"
    }

    private val testClient = client.newBuilder()
        .connectTimeout(5, TimeUnit.SECONDS)
        .readTimeout(5, TimeUnit.SECONDS)
        .build()

    suspend fun testMirrors(mirrors: List<MirrorItem>): List<MirrorItem> {
        return mirrors.map { mirror ->
            mirror.copy(reachable = testMirrorReachable(mirror.url))
        }
    }

    private suspend fun testMirrorReachable(url: String): Boolean {
        return try {
            val request = Request.Builder()
                .url("$url/")
                .head()
                .build()

            testClient.newCall(request).execute().use { response ->
                response.isSuccessful || response.code in 301..308
            }
        } catch (e: Exception) {
            false
        }
    }

    fun getMirrorUrl(mirror: String, originalUrl: String): String {
        return when {
            mirror.contains("ghproxy") -> "$mirror/$originalUrl"
            mirror.contains("fastgit") -> originalUrl.replace(
                "https://api.github.com",
                "$mirror/api.github.com"
            )
            mirror.contains("moeyy") -> "$mirror/$originalUrl"
            else -> "$mirror/$originalUrl"
        }
    }

    fun getDownloadMirrorUrl(mirror: String, originalUrl: String, useCdn: Boolean): String {
        if (!useCdn || mirror.isEmpty()) return originalUrl
        return when {
            mirror.contains("ghproxy") -> "$mirror/$originalUrl"
            mirror.contains("fastgit") -> originalUrl.replace(
                "https://github.com",
                "$mirror/github.com"
            )
            else -> originalUrl
        }
    }

    fun getDefaultMirrors(): List<MirrorItem> {
        return Constants.DEFAULT_MIRRORS.map { url ->
            MirrorItem(
                name = url.substringAfter("//").substringBefore("."),
                url = url,
                isDefault = true,
                remark = when {
                    url.contains("fastgit") -> "国内高速镜像"
                    url.contains("ghproxy") -> "代理加速"
                    url.contains("moeyy") -> "国内镜像"
                    else -> ""
                }
            )
        }
    }

    fun parseMirrorFromString(line: String): MirrorItem? {
        try {
            val parts = line.split("|", limit = 3)
            if (parts.size >= 2) {
                val name = parts[0].trim()
                val url = parts[1].trim()
                val remark = if (parts.size > 2) parts[2].trim() else ""
                return MirrorItem(
                    name = name,
                    url = if (url.startsWith("http://") || url.startsWith("https://")) url else "https://$url",
                    remark = remark,
                    isDefault = false
                )
            }
            // 如果只有URL
            if (line.contains("http")) {
                val url = line.trim()
                return MirrorItem(
                    name = url.substringAfter("//").substringBefore("."),
                    url = if (url.startsWith("http://") || url.startsWith("https://")) url else "https://$url",
                    isDefault = false
                )
            }
        } catch (e: Exception) {
            Logger.e(TAG, "解析镜像行失败: $line", e)
        }
        return null
    }

    fun formatMirrorToString(mirror: MirrorItem): String {
        return if (mirror.remark.isNotEmpty()) {
            "${mirror.name}|${mirror.url}|${mirror.remark}"
        } else {
            "${mirror.name}|${mirror.url}"
        }
    }
}

package com.UIN.Tool.data.remote

import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.util.concurrent.TimeUnit

object NetworkClient {

    private const val BASE_URL = "https://api.github.com/"

    private val okHttpClient by lazy {
        OkHttpClient.Builder()
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(60, TimeUnit.SECONDS)
            .addInterceptor(HttpLoggingInterceptor().apply {
                level = HttpLoggingInterceptor.Level.BASIC
            })
            .cache(okhttp3.Cache(
                java.io.File(com.UIN.Tool.UinApplication.getInstance().cacheDir, "okhttp_cache"),
                50 * 1024 * 1024
            ))
            .build()
    }

    private val retrofit by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .client(okHttpClient)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
    }

    fun <T> createService(serviceClass: Class<T>): T {
        return retrofit.create(serviceClass)
    }
}

