// ==================== 玻璃卡片 ====================

@Composable
fun GlassCard(
    modifier: Modifier = Modifier,
    onClick: (() -> Unit)? = null,
    content: @Composable ColumnScope.() -> Unit
) {
    val shape = RoundedCornerShape(16.dp)

    Surface(
        modifier = modifier
            .clip(shape)
            .clickable(enabled = onClick != null) { onClick?.invoke() },
        color = Color.White.copy(alpha = 0.85f),
        shadowElevation = 2.dp,
        shape = shape
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            content = content
        )
    }
}

// ==================== 玻璃按钮 ====================

@Composable
fun GlassButton(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    text: String? = null,
    icon: ImageVector? = null,
    colors: GlassButtonColors = GlassButtonColors.default()
) {
    val shape = RoundedCornerShape(12.dp)

    Surface(
        modifier = modifier
            .clip(shape)
            .clickable(enabled = enabled) { onClick() },
        color = colors.backgroundColor,
        shadowElevation = 2.dp,
        shape = shape
    ) {
        Row(
            modifier = Modifier
                .padding(horizontal = 16.dp, vertical = 12.dp),
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (icon != null) {
                Icon(
                    imageVector = icon,
                    contentDescription = null,
                    tint = colors.contentColor,
                    modifier = Modifier.size(20.dp)
                )
                if (text != null) Spacer(modifier = Modifier.width(8.dp))
            }
            if (text != null) {
                Text(
                    text = text,
                    color = colors.contentColor,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Medium
                )
            }
        }
    }
}

data class GlassButtonColors(
    val backgroundColor: Color,
    val contentColor: Color
) {
    companion object {
        fun default() = GlassButtonColors(
            backgroundColor = Color.White.copy(alpha = 0.85f),
            contentColor = Color(0xFF1A1A1A)
        )

        fun primary() = GlassButtonColors(
            backgroundColor = Color(0xFF1A1A1A).copy(alpha = 0.9f),
            contentColor = Color.White
        )

        fun secondary() = GlassButtonColors(
            backgroundColor = Color.White.copy(alpha = 0.5f),
            contentColor = Color(0xFF1A1A1A)
        )
    }
}

