@Composable
fun MainScreen(
    initialTab: Int = 1,
    checkUpdate: Boolean = false
) {
    var selectedTab by remember { mutableStateOf(initialTab) }

    val tabs = listOf(
        "开发" to R.drawable.ic_developer_mode,
        "工具" to R.drawable.ic_grid_view,
        "仓库" to R.drawable.ic_repo,
        "管理" to R.drawable.ic_settings
    )

    // 处理检查更新
    LaunchedEffect(checkUpdate) {
        if (checkUpdate) {
            selectedTab = 3 // 切换到管理页面
        }
    }

    Scaffold(
        bottomBar = {
            NavigationBar(
                containerColor = MaterialTheme.colorScheme.surface,
                tonalElevation = 8.dp
            ) {
                tabs.forEachIndexed { index, (label, icon) ->
                    NavigationBarItem(
                        selected = selectedTab == index,
                        onClick = { selectedTab = index },
                        icon = {
                            Icon(
                                painter = painterResource(id = icon),
                                contentDescription = label,
                                modifier = Modifier.size(24.dp)
                            )
                        },
                        label = { Text(label) },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = MaterialTheme.colorScheme.primary,
                            unselectedIconColor = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    )
                }
            }
        }
    ) { paddingValues ->
        Box(modifier = Modifier.fillMaxSize().padding(paddingValues)) {
            when (selectedTab) {
                0 -> DevScreen()
                1 -> ToolsScreen()
                2 -> RepoScreen()
                3 -> ManageScreen(checkUpdate = checkUpdate)
            }
        }
    }
}

