package com.UIN.Tool.utils

import android.annotation.SuppressLint
import android.content.Context
import android.content.Intent
import android.content.pm.ShortcutInfo
import android.content.pm.ShortcutManager
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.drawable.Icon
import android.os.Build
import android.widget.Toast
import com.UIN.Tool.MainActivity
import com.UIN.Tool.R
import com.UIN.Tool.domain.model.PluginInfo
import com.UIN.Tool.log.Logger
import com.UIN.Tool.plugin.PluginManager
import java.io.File

object PluginShortcutHelper {

    private const val TAG = "PluginShortcutHelper"

    /**
     * 创建插件快捷方式
     * 直接指向 MainActivity，通过 extra 传递插件ID
     */
    fun createShortcut(context: Context, plugin: PluginInfo) {
        if (!isShortcutSupported(context)) {
            Toast.makeText(context, "当前设备不支持创建快捷方式", Toast.LENGTH_SHORT).show()
            return
        }

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            createShortcutForOreoAndAbove(context, plugin)
        } else {
            createShortcutForOldVersions(context, plugin)
        }
    }

    private fun isShortcutSupported(context: Context): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val shortcutManager = context.getSystemService(ShortcutManager::class.java)
            return shortcutManager != null && shortcutManager.isRequestPinShortcutSupported
        }
        return true
    }

    @SuppressLint("NewApi")
    private fun createShortcutForOreoAndAbove(context: Context, plugin: PluginInfo) {
        val shortcutManager = context.getSystemService(ShortcutManager::class.java) ?: return

        // 检查是否已存在
        val existingShortcuts = shortcutManager.pinnedShortcuts
        for (info in existingShortcuts) {
            if (info.id == "plugin_${plugin.pluginId}") {
                Toast.makeText(context, "快捷方式已存在", Toast.LENGTH_SHORT).show()
                return
            }
        }

        // 直接指向 MainActivity，通过 extra 传递插件ID
        val intent = Intent(context, MainActivity::class.java).apply {
            putExtra("plugin_id", plugin.pluginId)
            putExtra("open_plugin", true)
            action = Intent.ACTION_VIEW
            // 不加任何 FLAG，让系统正常处理
        }

        val icon = getPluginIcon(context, plugin)
        if (icon == null) {
            Toast.makeText(context, "无法获取插件图标", Toast.LENGTH_SHORT).show()
            return
        }

        val shortcut = ShortcutInfo.Builder(context, "plugin_${plugin.pluginId}")
            .setShortLabel(plugin.name)
            .setLongLabel(plugin.description.ifEmpty { plugin.name })
            .setIcon(icon)
            .setIntent(intent)
            .build()

        val success = shortcutManager.requestPinShortcut(shortcut, null)
        if (success) {
            Toast.makeText(context, "快捷方式已创建", Toast.LENGTH_SHORT).show()
        }
    }

    @Suppress("DEPRECATION")
    private fun createShortcutForOldVersions(context: Context, plugin: PluginInfo) {
        // 直接指向 MainActivity，通过 extra 传递插件ID
        val shortcutIntent = Intent(context, MainActivity::class.java).apply {
            putExtra("plugin_id", plugin.pluginId)
            putExtra("open_plugin", true)
            action = Intent.ACTION_VIEW
        }

        val addIntent = Intent().apply {
            putExtra(Intent.EXTRA_SHORTCUT_INTENT, shortcutIntent)
            putExtra(Intent.EXTRA_SHORTCUT_NAME, plugin.name)
            action = "com.android.launcher.action.INSTALL_SHORTCUT"
        }

        val bitmap = getPluginIconBitmap(context, plugin)
        if (bitmap != null) {
            addIntent.putExtra(Intent.EXTRA_SHORTCUT_ICON, bitmap)
        } else {
            addIntent.putExtra(
                Intent.EXTRA_SHORTCUT_ICON_RESOURCE,
                Intent.ShortcutIconResource.fromContext(context, R.drawable.ic_extension)
            )
        }

        context.sendBroadcast(addIntent)
        Toast.makeText(context, "快捷方式已创建", Toast.LENGTH_SHORT).show()
    }

    @SuppressLint("NewApi")
    private fun getPluginIcon(context: Context, plugin: PluginInfo): Icon? {
        val bitmap = getPluginIconBitmap(context, plugin)
        return if (bitmap != null && Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val scaled = Bitmap.createScaledBitmap(bitmap, 72, 72, true)
            Icon.createWithBitmap(scaled)
        } else {
            null
        }
    }

    private fun getPluginIconBitmap(context: Context, plugin: PluginInfo): Bitmap? {
        return try {
            val pluginDir = File(Constants.PLUGIN_DIR, plugin.pluginId)
            if (pluginDir.exists()) {
                val iconPath = if (plugin.icon.isNotEmpty()) plugin.icon else "icon.png"
                val iconFile = File(pluginDir, iconPath)
                if (iconFile.exists()) {
                    val options = BitmapFactory.Options().apply { inSampleSize = 2 }
                    BitmapFactory.decodeFile(iconFile.absolutePath, options)
                } else null
            } else null
        } catch (e: Exception) {
            Logger.e(TAG, "获取插件图标失败", e)
            null
        }
    }

    @Suppress("DEPRECATION", "NewApi")
    fun removeShortcut(context: Context, plugin: PluginInfo) {
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                val shortcutManager = context.getSystemService(ShortcutManager::class.java)
                shortcutManager?.removeDynamicShortcuts(listOf("plugin_${plugin.pluginId}"))
                Toast.makeText(context, "快捷方式已移除", Toast.LENGTH_SHORT).show()
            } else {
                val removeIntent = Intent().apply {
                    putExtra(Intent.EXTRA_SHORTCUT_INTENT, Intent(context, MainActivity::class.java))
                    putExtra(Intent.EXTRA_SHORTCUT_NAME, plugin.name)
                    action = "com.android.launcher.action.UNINSTALL_SHORTCUT"
                }
                context.sendBroadcast(removeIntent)
                Toast.makeText(context, "快捷方式已移除", Toast.LENGTH_SHORT).show()
            }
        } catch (e: Exception) {
            Logger.e(TAG, "移除快捷方式失败", e)
            Toast.makeText(context, "移除快捷方式失败", Toast.LENGTH_SHORT).show()
        }
    }

    fun isShortcutExists(context: Context, pluginId: String): Boolean {
        return try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                val shortcutManager = context.getSystemService(ShortcutManager::class.java)
                val pinnedShortcuts = shortcutManager?.pinnedShortcuts ?: return false
                pinnedShortcuts.any { it.id == "plugin_$pluginId" }
            } else {
                false
            }
        } catch (e: Exception) {
            false
        }
    }
}

package com.UIN.Tool.utils

import com.UIN.Tool.plugin.PluginManager
import com.UIN.Tool.data.local.PreferenceManager
import com.UIN.Tool.log.Logger
import java.io.File
import java.io.FileInputStream
import java.security.MessageDigest

object SecurityUtils {

    private const val TAG = "SecurityUtils"

    fun verifyFileSignature(file: File, preferenceManager: PreferenceManager): Boolean {
        if (PluginManager.isIgnoreSignatureWarning()) {
            Logger.w(TAG, "签名验证已忽略")
            return true
        }

        val fileHash = calculateFileHash(file) ?: return false
        val expectedHash = preferenceManager.getPluginSignature(file.name)

        return if (expectedHash.isNullOrEmpty()) {
            preferenceManager.savePluginSignature(file.name, fileHash)
            Logger.i(TAG, "首次导入，记录签名: ${file.name}")
            true
        } else {
            val verified = expectedHash == fileHash
            if (!verified) {
                Logger.e(TAG, "签名验证失败！文件可能被篡改: ${file.name}")
            } else {
                Logger.success(TAG, "签名验证通过: ${file.name}")
            }
            verified
        }
    }

    fun calculateFileHash(file: File): String? {
        return try {
            val md = MessageDigest.getInstance("SHA-256")
            FileInputStream(file).use { fis ->
                val buffer = ByteArray(8192)
                var len: Int
                while (fis.read(buffer).also { len = it } > 0) {
                    md.update(buffer, 0, len)
                }
            }
            md.digest().joinToString("") { "%02x".format(it) }
        } catch (e: Exception) {
            Logger.e(TAG, "计算哈希失败: ${file.absolutePath}", e)
            null
        }
    }

    fun savePluginSignature(pluginId: String, file: File, preferenceManager: PreferenceManager) {
        val hash = calculateFileHash(file)
        if (hash != null) {
            preferenceManager.savePluginSignature(pluginId, hash)
            Logger.i(TAG, "保存插件签名: $pluginId")
        }
    }

    fun isValidSha256(hash: String): Boolean {
        return hash.matches(Regex("^[a-fA-F0-9]{64}$"))
    }
}

package com.UIN.Tool.utils

import android.content.Context
import com.UIN.Tool.log.Logger

object TemplateUtils {

    private const val TAG = "TemplateUtils"
    private const val TEMPLATE_BASE_PATH = "plugin_templates/"

    fun loadTemplate(context: Context, templatePath: String): String {
        return try {
            context.assets.open("$TEMPLATE_BASE_PATH$templatePath").bufferedReader().use {
                it.readText()
            }
        } catch (e: Exception) {
            Logger.e(TAG, "加载模板失败: $templatePath", e)
            ""
        }
    }

    fun renderTemplate(template: String, variables: Map<String, String>): String {
        var result = template
        variables.forEach { (key, value) ->
            result = result.replace("{{$key}}", value ?: "")
        }
        return result
    }

    fun generateJavaCode(
        context: Context,
        uiType: String,
        variables: Map<String, String>
    ): String {
        val templatePath = if (uiType == "web") "WebPlugin.java.tmpl" else "NativePlugin.java.tmpl"
        val template = loadTemplate(context, templatePath)
        return renderTemplate(template, variables)
    }

    fun generateReadme(
        context: Context,
        variables: Map<String, String>
    ): String {
        val template = loadTemplate(context, "README.md.tmpl")
        return renderTemplate(template, variables)
    }

    fun generateWebTemplates(
        context: Context,
        variables: Map<String, String>,
        templateType: Int
    ): Map<String, String> {
        val files = mutableMapOf<String, String>()

        if (templateType == 2) return files

        val indexTemplate = if (templateType == 1) {
            loadTemplate(context, "web/blank_index.html")
        } else {
            loadTemplate(context, "web/index.html")
        }
        files["web/index.html"] = renderTemplate(indexTemplate, variables)

        if (templateType == 0) {
            val cssTemplate = loadTemplate(context, "web/style.css")
            val jsTemplate = loadTemplate(context, "web/script.js")
            files["web/style.css"] = renderTemplate(cssTemplate, variables)
            files["web/script.js"] = renderTemplate(jsTemplate, variables)
        }

        return files
    }

    fun generatePluginJson(variables: Map<String, String>): String {
        return """
            {
                "pluginId": "${variables["pluginId"] ?: ""}",
                "version": ${variables["version"] ?: 1},
                "versionName": "${variables["versionName"] ?: "1.0.0"}",
                "minHostVersion": 1,
                "name": "${variables["name"] ?: ""}",
                "author": "${variables["author"] ?: ""}",
                "description": "${variables["description"] ?: ""}",
                "icon": "icon.png",
                "mainClass": "${variables["mainClass"] ?: ""}",
                "apiLevel": 21,
                "uiType": "${variables["uiType"] ?: "native"}",
                "entry": "${variables["entry"] ?: "web/index.html"}",
                "permissions": [],
                "dependencies": "${variables["dependencies"] ?: ""}"
            }
        """.trimIndent()
    }
}

// app/src/main/java/com/UIN/Tool/utils/UIConfig.kt
package com.UIN.Tool.utils

import android.content.Context
import android.graphics.Color
import com.UIN.Tool.log.Logger
import org.json.JSONObject

object UIConfig {

    private const val TAG = "UIConfig"
    private const val PREF_NAME = "ui_config"
    private const val KEY_CONFIG = "config_json"
    private const val KEY_USE_ICON_TINT = "use_icon_tint"
    private const val KEY_CURRENT_THEME = "current_theme"

    private lateinit var context: Context
    internal var config: JSONObject = JSONObject()
    private var useIconTint: Boolean = true
    private var currentTheme: String = "default"
    private var isInitialized = false

    fun init(context: Context) {
        if (isInitialized) return
        this.context = context.applicationContext
        loadConfig()
        isInitialized = true
        Logger.i(TAG, "UIConfig初始化完成")
    }

    fun getInstance(): UIConfig {
        if (!isInitialized) {
            throw IllegalStateException("UIConfig未初始化，请先调用init()")
        }
        return this
    }

    private fun loadConfig() {
        val prefs = context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)
        val configJson = prefs.getString(KEY_CONFIG, null)

        if (configJson != null) {
            try {
                config = JSONObject(configJson)
            } catch (e: Exception) {
                Logger.e(TAG, "解析配置失败，使用默认配置", e)
                config = getDefaultConfig()
            }
        } else {
            config = getDefaultConfig()
        }

        useIconTint = prefs.getBoolean(KEY_USE_ICON_TINT, true)
        currentTheme = prefs.getString(KEY_CURRENT_THEME, "default") ?: "default"
    }

    fun saveConfig() {
        val prefs = context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)
        prefs.edit().apply {
            putString(KEY_CONFIG, config.toString())
            putBoolean(KEY_USE_ICON_TINT, useIconTint)
            putString(KEY_CURRENT_THEME, currentTheme)
        }.apply()
        Logger.d(TAG, "配置已保存")
    }

    fun getConfig(): JSONObject = config

    private fun getDefaultConfig(): JSONObject {
        return try {
            JSONObject().apply {
                put("theme", JSONObject().apply {
                    put("primary", "#FF1A3A4A")
                    put("primary_dark", "#FF0F2838")
                    put("primary_light", "#FF2D5A70")
                    put("accent", "#FF4A8A9E")
                    put("success", "#FF4CAF50")
                    put("warning", "#FFFF9800")
                    put("error", "#FFF44336")
